        placeholder="Username (must contain @)"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      {showOtpField && (
        <>
          <p>Enter OTP:</p>
          <OtpInput value={otp} onChange={setOtp} />
