    }

    const phoneRegex = /^\+92[\s\-]?\(?(\d{3})\)?[\s\-]?\d{7}$/;
    if (phoneRegex.test(phone)) {
      setError((prevError) =>
        prevError === "Invalid phone number. Please use the format +92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX."
          ? ""
          : prevError
      );
    }
  }, [email, phone]);

  return (
