        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password (min 8 characters)"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (+92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX)"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        className="input"
      />
      {showOtpField && (
        <>
          <p>Enter OTP:</p>
          <OtpInput value={otp} onChange={setOtp} />
        </>
